"use client";

import { useState, useMemo, useEffect } from "react";
import { Link } from "@/i18n/navigation";
import {
  Search,
  Plus,
  ChevronLeft,
  ChevronRight,
  Eye,
  Pencil,
  Trash2,
  Filter,
  Loader2,
} from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { useLocale, useTranslations } from "next-intl";
import { useFamiliesStore } from "@/lib/store";
import { AddFamilyForm } from "@/components/add-family-form";
import { formatLocaleNumber } from "@/lib/format/locale-format";
import type { AppLocale } from "@/lib/i18n/locales";

const classificationColors: Record<string, string> = {
  VERY_FRAGILE: "bg-destructive/15 text-destructive border-destructive/30",
  FRAGILE: "bg-destructive/10 text-destructive border-destructive/25",
  WEAK: "bg-warning/15 text-warning-foreground border-warning/30",
  MODERATE: "bg-primary/12 text-primary border-primary/25",
  OUT_OF_PRIORITY: "bg-muted text-muted-foreground border-border",
};

const PAGE_SIZE = 10;

const VULN_KEYS = ["VERY_FRAGILE", "FRAGILE", "WEAK", "MODERATE", "OUT_OF_PRIORITY"] as const;

export default function FamiliesPage() {
  const { families, filters, setFilters, deleteFamily, fetchFamilies, loading } = useFamiliesStore();
  const [page, setPage] = useState(1);
  const [sortField, setSortField] = useState<string | null>(null);
  const [sortDir, setSortDir] = useState("asc");
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingFamily, setEditingFamily] = useState<Record<string, unknown> | null>(null);

  const t = useTranslations("families.list");
  const tDomain = useTranslations("domain");
  const locale = useLocale() as AppLocale;
  const collatorLocale = locale === "ar" ? "ar" : "en";

  useEffect(() => {
    fetchFamilies();
  }, []);

  const sortedFamilies = useMemo(() => {
    let result = [...families];

    if (sortField) {
      result.sort((a, b) => {
        const aVal = (a as Record<string, unknown>)[sortField];
        const bVal = (b as Record<string, unknown>)[sortField];
        if (typeof aVal === "number" && typeof bVal === "number") {
          return sortDir === "asc" ? aVal - bVal : bVal - aVal;
        }
        return sortDir === "asc"
          ? String(aVal).localeCompare(String(bVal), collatorLocale)
          : String(bVal).localeCompare(String(aVal), collatorLocale);
      });
    }

    return result;
  }, [families, sortField, sortDir, collatorLocale]);

  const totalPages = Math.ceil(sortedFamilies.length / PAGE_SIZE);
  const paginated = sortedFamilies.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  const handleSort = (field: string) => {
    if (sortField === field) {
      setSortDir((d) => (d === "asc" ? "desc" : "asc"));
    } else {
      setSortField(field);
      setSortDir("asc");
    }
  };

  const classificationLabel = (code: string) => {
    const k = code as (typeof VULN_KEYS)[number];
    if (VULN_KEYS.includes(k)) {
      return tDomain(`vulnerability.${k}`);
    }
    return code;
  };

  const fmtMoney = (n: number) =>
    `${formatLocaleNumber(locale, n, { maximumFractionDigits: 0 })} ${t("currency")}`;

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-foreground">{t("title")}</h2>
          <p className="text-muted-foreground text-sm mt-1">
            {t("subtitle", { count: families.length })}
          </p>
        </div>
        <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
          <DialogTrigger asChild>
            <Button className="gap-2 bg-green-600 hover:bg-green-700 text-white rounded-lg px-4 py-2">
              <Plus className="h-4 w-4" />
              {t("addFamily")}
            </Button>
          </DialogTrigger>
          <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>{t("dialogAdd")}</DialogTitle>
            </DialogHeader>
            <AddFamilyForm onSuccess={() => { setDialogOpen(false); fetchFamilies(); }} />
          </DialogContent>
        </Dialog>
      </div>

      <Dialog open={!!editingFamily} onOpenChange={(val) => !val && setEditingFamily(null)}>
        {editingFamily && (
          <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>{t("dialogEdit")}</DialogTitle>
            </DialogHeader>
            <AddFamilyForm
              initialData={editingFamily}
              onSuccess={() => setEditingFamily(null)}
            />
          </DialogContent>
        )}
      </Dialog>

      <Card className="border-0 shadow-sm">
        <CardContent className="p-4">
          <div className="flex flex-col sm:flex-row gap-3">
            <div className="relative flex-1">
              <Search className="absolute end-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder={t("searchPlaceholder")}
                value={filters.search}
                onChange={(e) => {
                  setFilters({ search: e.target.value });
                  setPage(1);
                }}
                className="ps-10"
              />
            </div>
            <Select
              value={filters.classification}
              onValueChange={(val) => {
                setFilters({ classification: val });
                setPage(1);
              }}
            >
              <SelectTrigger className="w-full sm:w-48">
                <Filter className="h-4 w-4 me-2 text-muted-foreground" />
                <SelectValue placeholder={t("filterClassification")} />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">{t("classificationAll")}</SelectItem>
                {VULN_KEYS.map((k) => (
                  <SelectItem key={k} value={k}>
                    {tDomain(`vulnerability.${k}`)}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </CardContent>
      </Card>

      <Card className="border-0 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <Table>
            <TableHeader>
              <TableRow className="hover:bg-transparent">
                <TableHead
                  className="cursor-pointer hover:text-foreground transition-colors text-start"
                  onClick={() => handleSort("headName")}
                >
                  {t("table.headName")}
                </TableHead>
                <TableHead className="text-start">{t("table.nationalId")}</TableHead>
                <TableHead className="text-start">{t("table.phone")}</TableHead>
                <TableHead
                  className="cursor-pointer hover:text-foreground transition-colors text-start"
                  onClick={() => handleSort("members")}
                >
                  {t("table.members")}
                </TableHead>
                <TableHead
                  className="cursor-pointer hover:text-foreground transition-colors text-start"
                  onClick={() => handleSort("totalIncome")}
                >
                  {t("table.totalIncome")}
                </TableHead>
                <TableHead
                  className="cursor-pointer hover:text-foreground transition-colors text-start"
                  onClick={() => handleSort("vulnerabilityIndex")}
                >
                  {t("table.vulnerabilityIndex")}
                </TableHead>
                <TableHead className="text-start">{t("table.classification")}</TableHead>
                <TableHead className="text-start">{t("table.actions")}</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading ? (
                <TableRow>
                  <TableCell colSpan={8} className="h-32 text-center">
                    <div className="flex flex-col items-center gap-2 text-muted-foreground">
                      <Loader2 className="h-8 w-8 animate-spin" />
                      <p>{t("loading")}</p>
                    </div>
                  </TableCell>
                </TableRow>
              ) : paginated.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={8} className="h-32 text-center">
                    <div className="flex flex-col items-center gap-2 text-muted-foreground">
                      <Search className="h-8 w-8" />
                      <p>{t("empty")}</p>
                    </div>
                  </TableCell>
                </TableRow>
              ) : (
                paginated.map((family: Record<string, unknown> & { id: string | number }) => (
                  <TableRow key={String(family.id)} className="hover:bg-accent/50 transition-colors">
                    <TableCell className="font-medium">{String(family.headName ?? "")}</TableCell>
                    <TableCell className="font-mono text-sm" dir="ltr">
                      {String(family.nationalId ?? "")}
                    </TableCell>
                    <TableCell className="font-mono text-sm" dir="ltr">
                      {String(family.phone ?? "")}
                    </TableCell>
                    <TableCell>
                      {Array.isArray(family.members) ? family.members.length : Number(family.members ?? 0)}
                    </TableCell>
                    <TableCell>{fmtMoney(Number(family.totalIncome ?? 0))}</TableCell>
                    <TableCell>
                      <div className="flex items-center gap-2">
                        <div className="h-2 w-16 bg-secondary rounded-full overflow-hidden">
                          <div
                            className="h-full bg-primary rounded-full transition-all"
                            style={{
                              width: `${Math.min((Number(family.vulnerabilityIndex) || 0) * 10, 100)}%`,
                            }}
                          />
                        </div>
                        <span className="text-sm tabular-nums">
                          {formatLocaleNumber(locale, Math.min((Number(family.vulnerabilityIndex) || 0) * 10, 100), {
                            maximumFractionDigits: 0,
                          })}
                          {t("percent")}
                        </span>
                      </div>
                    </TableCell>
                    <TableCell>
                      <Badge
                        variant="outline"
                        className={classificationColors[String(family.classification)] ?? ""}
                      >
                        {classificationLabel(String(family.classification))}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-1">
                        <Button variant="ghost" size="icon" className="h-8 w-8" asChild>
                          <Link href={`/dashboard/families/${family.id}`}>
                            <Eye className="h-4 w-4" />
                            <span className="sr-only">{t("sr.view")}</span>
                          </Link>
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8"
                          onClick={() => setEditingFamily(family)}
                        >
                          <Pencil className="h-4 w-4" />
                          <span className="sr-only">{t("sr.edit")}</span>
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 text-destructive hover:text-destructive"
                          onClick={() => {
                            if (window.confirm(t("deleteConfirm"))) {
                              deleteFamily(family.id);
                              import("sonner").then((m) => m.toast.success(t("deleteSuccess")));
                            }
                          }}
                        >
                          <Trash2 className="h-4 w-4" />
                          <span className="sr-only">{t("sr.delete")}</span>
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </div>

        {totalPages > 1 && (
          <div className="flex items-center justify-between p-4 border-t border-border">
            <p className="text-sm text-muted-foreground">
              {t("pagination", {
                from: (page - 1) * PAGE_SIZE + 1,
                to: Math.min(page * PAGE_SIZE, sortedFamilies.length),
                total: sortedFamilies.length,
              })}
            </p>
            <div className="flex items-center gap-1">
              <Button
                variant="outline"
                size="icon"
                className="h-8 w-8"
                disabled={page === 1}
                onClick={() => setPage(page - 1)}
              >
                <ChevronRight className="h-4 w-4 rtl:rotate-180" />
              </Button>
              {Array.from({ length: totalPages }, (_, i) => i + 1).map((p) => (
                <Button
                  key={p}
                  variant={p === page ? "default" : "outline"}
                  size="icon"
                  className="h-8 w-8"
                  onClick={() => setPage(p)}
                >
                  {p}
                </Button>
              ))}
              <Button
                variant="outline"
                size="icon"
                className="h-8 w-8"
                disabled={page === totalPages}
                onClick={() => setPage(page + 1)}
              >
                <ChevronLeft className="h-4 w-4 rtl:rotate-180" />
              </Button>
            </div>
          </div>
        )}
      </Card>
    </div>
  );
}

"use client";

import dynamic from "next/dynamic";
import { RefreshCw } from "lucide-react";
import { useEffect, useMemo } from "react";
import { useTranslations } from "next-intl";
import { useDashboardStore } from "@/lib/store";
import { OperationalStrip } from "@/components/dashboard/operational-strip";
import { FinancialIntelligenceRow } from "@/components/dashboard/financial-intelligence-row";
import { FamilyStatsStrip } from "@/components/dashboard/family-stats-strip";
import { RegionalCompactTable } from "@/components/dashboard/regional-compact-table";
import { RecentFamiliesTable, type RecentFamilyRow } from "@/components/dashboard/recent-families-table";
import { PriorityFamiliesTable, type PriorityFamilyRow } from "@/components/dashboard/priority-families-table";
import { AlertsFeed } from "@/components/dashboard/alerts-feed";
import type { RegionDatum } from "@/components/dashboard/region-overview-card";
import type { PredictionPayload } from "@/components/dashboard/financial-forecast-strip";
import type { WorkflowQueueRow } from "@/components/dashboard/workflow-queue-card";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

const DashboardAnalytics = dynamic(
  () => import("@/components/dashboard/analytics-grid").then((m) => ({ default: m.AnalyticsGrid })),
  {
    ssr: false,
    loading: () => (
      <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">
        {Array.from({ length: 4 }).map((_, i) => (
          <div key={i} className="h-[248px] rounded-lg border border-border/40 bg-muted/20 animate-pulse" />
        ))}
      </div>
    ),
  }
);

export default function DashboardPage() {
  const t = useTranslations("dashboard");
  const {
    stats,
    familyClassification,
    classificationExpenses,
    monthlySeries,
    prediction,
    regionsOverview,
    workflow,
    fetchDashboardBundle,
    loadingDashboard,
    dashboardError,
    dashboardErrors,
  } = useDashboardStore();

  useEffect(() => {
    fetchDashboardBundle();
  }, [fetchDashboardBundle]);

  const queueRows: WorkflowQueueRow[] = Array.isArray((workflow as Record<string, unknown> | null)?.queueRows)
    ? (workflow as { queueRows: WorkflowQueueRow[] }).queueRows
    : [];

  const predictionPayload = prediction as PredictionPayload | null;

  const regionData: RegionDatum[] = Array.isArray(regionsOverview) ? regionsOverview : [];

  const recentRows: RecentFamilyRow[] = Array.isArray((workflow as Record<string, unknown> | null)?.recentFamilies)
    ? (workflow as { recentFamilies: RecentFamilyRow[] }).recentFamilies
    : [];

  const priorityRows: PriorityFamilyRow[] = Array.isArray((workflow as Record<string, unknown> | null)?.priorityFamilies)
    ? (workflow as { priorityFamilies: PriorityFamilyRow[] }).priorityFamilies
    : [];

  const backlog = Number((workflow as Record<string, unknown> | null)?.registrationBacklogFamilies ?? 0);
  const overdueMedical = Number((workflow as Record<string, unknown> | null)?.overdueMedicalReviews ?? 0);

  const pendingFieldResearchSum = useMemo(
    () => regionData.reduce((s, r) => s + (r.pendingResearch ?? 0), 0),
    [regionData]
  );

  const fieldActivityVolume = useMemo(
    () => backlog + queueRows.length + pendingFieldResearchSum,
    [backlog, queueRows.length, pendingFieldResearchSum]
  );

  const partialFailure = useMemo(
    () => Object.values(dashboardErrors).some((e) => e != null),
    [dashboardErrors]
  );

  const workflowFailed = !!dashboardErrors.workflow;

  const statsLoading = loadingDashboard && !dashboardErrors.stats;

  return (
    <div className="mx-auto max-w-[1200px] space-y-4 px-1 pb-12">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div className="space-y-0.5">
          <h1 className="text-xl font-bold tracking-tight text-foreground md:text-2xl">{t("header.title")}</h1>
          <p className="text-xs text-muted-foreground md:text-sm">{t("header.subtitle")}</p>
        </div>
        <Button
          variant="outline"
          size="sm"
          disabled={loadingDashboard}
          onClick={() => fetchDashboardBundle(true)}
          className="h-8 shrink-0 gap-2 rounded-lg border-border/60 text-xs"
        >
          <RefreshCw className={`size-3.5 ${loadingDashboard ? "animate-spin" : ""}`} />
          {t("common.retry")}
        </Button>
      </div>

      {dashboardError ? (
        <Alert variant="destructive" className="rounded-lg">
          <AlertTitle>{t("common.error")}</AlertTitle>
          <AlertDescription>{t("common.retry")}</AlertDescription>
        </Alert>
      ) : null}

      {partialFailure && !dashboardError ? (
        <Alert className="rounded-lg border-warning/35 bg-warning/8">
          <AlertTitle className="text-xs font-semibold">{t("common.partial_banner")}</AlertTitle>
          <AlertDescription className="text-[11px] opacity-90">
            {[
              dashboardErrors.stats && `stats: ${dashboardErrors.stats}`,
              dashboardErrors.prediction && `prediction: ${dashboardErrors.prediction}`,
              dashboardErrors.regions && `regions: ${dashboardErrors.regions}`,
              dashboardErrors.workflow && `workflow: ${dashboardErrors.workflow}`,
            ]
              .filter(Boolean)
              .join(" · ")}
          </AlertDescription>
        </Alert>
      ) : null}

      <OperationalStrip
        submittedNotEvaluated={backlog}
        criticalNotEvaluated={Number(stats?.criticalFamilies ?? 0)}
        researchInProgress={dashboardErrors.regions ? null : pendingFieldResearchSum}
        awaitingFinalReview={workflowFailed ? 0 : queueRows.length}
        needingImmediateIntervention={Number(stats?.incompleteFamilies ?? 0)}
        criticalMedicalCases={Number(stats?.criticalMedical ?? 0)}
        loading={loadingDashboard}
      />

      <FinancialIntelligenceRow
        monthlySeries={monthlySeries ?? []}
        prediction={predictionPayload}
        loading={loadingDashboard}
        predictionFailed={!!dashboardErrors.prediction}
      />

      <FamilyStatsStrip
        totalFamilies={Number(stats?.totalFamilies ?? 0)}
        familyClassification={familyClassification ?? []}
        fieldActivityVolume={fieldActivityVolume}
        loading={statsLoading}
      />

      <DashboardAnalytics
        familyClassification={familyClassification ?? []}
        classificationExpenses={classificationExpenses ?? []}
        monthlySeries={monthlySeries ?? []}
        loading={statsLoading}
      />

      <RegionalCompactTable regions={regionData} loading={loadingDashboard && !dashboardErrors.regions} />

      <section className="space-y-2">
        <h2 className="text-sm font-bold text-foreground">{t("sections.action_center")}</h2>
        <div className="grid grid-cols-1 gap-4 lg:grid-cols-3">
          <RecentFamiliesTable rows={recentRows} loading={loadingDashboard && !workflowFailed} />
          <PriorityFamiliesTable rows={priorityRows} loading={loadingDashboard && !workflowFailed} />
          <AlertsFeed
            pendingEvaluations={Number(stats?.incompleteFamilies ?? 0)}
            backlogFamilies={backlog}
            overdueMedical={workflowFailed ? 0 : overdueMedical}
            staleQueueCount={workflowFailed ? 0 : queueRows.length}
            prediction={predictionPayload}
            predictionFailed={!!dashboardErrors.prediction}
            loading={loadingDashboard}
          />
        </div>
      </section>
    </div>
  );
}

"use client";

import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useFamiliesStore } from "@/lib/store";
import api from "@/lib/api/client";
import { Loader2, User, Phone, MapPin, CreditCard, FileText } from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";

const formSchema = z.object({
  name: z.string().min(4, "يجب أن يكون الاسم 4 حروف على الأقل"),
  spouseName: z.string().optional(),
  nationalId: z.string().length(14, "الرقم القومي يجب أن يكون 14 رقماً").regex(/^\d+$/, "أرقام فقط"),
  spouseNationalId: z.string().optional().refine(val => !val || (val.length === 14 && /^\d+$/.test(val)), "الرقم القومي يجب أن يكون 14 رقماً"),
  phone: z.string().regex(/^01\d{9}$/, "رقم الهاتف غير صحيح"),
  alternatePhone: z.string().optional().refine(val => !val || /^01\d{9}$/.test(val), "رقم الهاتف غير صحيح"),
  address: z.string().min(10, "العنوان يجب أن يكون 10 حروف على الأقل"),
  meezaCardNumber: z.string().optional().refine(val => !val || (val.length === 16 && /^\d+$/.test(val)), "رقم البطاقة يجب أن يكون 16 رقماً"),
  classification: z.string().min(1, "هذا الحقل مطلوب"),
  assistanceDecision: z.string().min(1, "هذا الحقل مطلوب"),
});

type FamilyFormValues = z.infer<typeof formSchema>;

export function AddFamilyForm({ onSuccess, initialData }: { onSuccess?: () => void; initialData?: any }) {
  const addFamily = useFamiliesStore(state => state.addFamily);
  const updateFamily = useFamiliesStore(state => state.updateFamily);
  const [loading, setLoading] = useState(false);
  const isEdit = !!initialData;

  const {
    register,
    handleSubmit,
    setValue,
    watch,
    formState: { errors },
    reset,
  } = useForm<FamilyFormValues>({
    resolver: zodResolver(formSchema),
    defaultValues: initialData ? {
      name: initialData.headName || initialData.name || "",
      spouseName: initialData.spouseName || "",
      nationalId: initialData.nationalId || "",
      spouseNationalId: initialData.spouseNationalId || "",
      phone: initialData.phone || "",
      alternatePhone: initialData.alternatePhone || "",
      address: initialData.address || "",
      meezaCardNumber: initialData.meezaCardNumber || "",
      classification: initialData.classification || "MODERATE_NEED",
      assistanceDecision: initialData.assistanceDecision || "PENDING",
    } : {
      name: "",
      spouseName: "",
      nationalId: "",
      spouseNationalId: "",
      phone: "",
      alternatePhone: "",
      address: "",
      meezaCardNumber: "",
      classification: "",
      assistanceDecision: "",
    },
  });

  const onSubmit = async (data: FamilyFormValues) => {
    try {
      setLoading(true);

      const notesJson = JSON.stringify({
        meezaCardNumber: data.meezaCardNumber,
        alternatePhone: data.alternatePhone,
        spouseNationalId: data.spouseNationalId,
        spouseName: data.spouseName,
      });

      if (isEdit) {
        await api.put(`/v1/families/${initialData.id}`, {
          address: data.address,
          phone: data.phone,
          notes: notesJson,
          social_status: data.classification,
        });
        updateFamily(initialData.id, { 
          headName: data.name,
          nationalId: data.nationalId,
          phone: data.phone,
          address: data.address,
          classification: data.classification,
          assistanceDecision: data.assistanceDecision
        });
        toast.success("تم تعديل بيانات الأسرة بنجاح");
        onSuccess?.();
        return;
      }

      const payload = {
        family: {
          registration_number: data.nationalId,
          address: data.address,
          housing_type: "RENT",
          phone: data.phone,
          notes: notesJson,
          social_status: data.classification,
        },
        persons: [
          {
            full_name: data.name,
            national_id: data.nationalId,
            role_in_family: "HUSBAND",
            gender: "MALE",
            smoker: false,
            disability: false,
          },
          ...(data.spouseName ? [{
            full_name: data.spouseName,
            national_id: data.spouseNationalId || null,
            role_in_family: "WIFE",
            gender: "FEMALE",
            smoker: false,
            disability: false,
          }] : []),
        ],
        incomes: [],
        medicalCases: [],
        educationRecords: [],
      };

      const response = await api.post("/v1/families", payload);

      addFamily({
        ...data,
        id: response.data.familyId || Math.random().toString(),
        headName: data.name,
        classification: data.classification,
        assistanceDecision: data.assistanceDecision,
        vulnerabilityIndex: 0,
