"use client";

import * as React from "react";
import { Link } from "@/i18n/navigation";
import { Bell, ChevronLeft, ChevronRight } from "lucide-react";
import { useLocale, useTranslations } from "next-intl";
import { cn } from "@/lib/utils";
import type { PredictionPayload } from "@/components/dashboard/financial-forecast-strip";

export interface AlertsFeedProps {
  pendingEvaluations: number;
  backlogFamilies: number;
  overdueMedical: number;
  staleQueueCount: number;
  prediction: PredictionPayload | null;
  predictionFailed?: boolean;
  loading?: boolean;
}

type FeedRow = { id: string; tone: "default" | "amber" | "rose"; text: string; count?: number; minutesAgo: number };

/** Reference: latest alerts column with relative timestamps (client-only to avoid hydration mismatch) */
export function AlertsFeed({
  pendingEvaluations,
  backlogFamilies,
  overdueMedical,
  staleQueueCount,
  prediction,
  predictionFailed,
  loading,
}: AlertsFeedProps) {
  const locale = useLocale();
  const t = useTranslations("dashboard");
  const [hydrated, setHydrated] = React.useState(false);
  React.useEffect(() => {
    setHydrated(true);
  }, []);

  const Chevron = locale === "ar" ? ChevronLeft : ChevronRight;

  const rows = React.useMemo(() => {
    const out: FeedRow[] = [];
    let tmin = 4;
    if (pendingEvaluations > 0) {
      out.push({
        id: "pe",
        tone: "amber",
        text: t("feed.overdue_evaluations"),
        count: pendingEvaluations,
        minutesAgo: tmin,
      });
      tmin += 6;
    }
    if (backlogFamilies > 0) {
      out.push({
        id: "bl",
        tone: "amber",
        text: t("feed.new_family_urgent_eval"),
        count: backlogFamilies,
        minutesAgo: tmin,
      });
      tmin += 7;
    }
    if (overdueMedical > 0) {
      out.push({
        id: "om",
        tone: "rose",
        text: t("feed.urgent_medical_cases"),
        count: overdueMedical,
        minutesAgo: tmin,
      });
      tmin += 5;
    }
    if (staleQueueCount > 0) {
      out.push({
        id: "st",
        tone: "amber",
        text: t("feed.stale_research"),
        count: staleQueueCount,
        minutesAgo: tmin,
      });
      tmin += 8;
    }
    if (!predictionFailed && prediction?.financialRiskLevel === "HIGH") {
      out.push({ id: "rk", tone: "rose", text: t("feed.critical_financial_signal"), minutesAgo: tmin + 3 });
    }
    return out;
  }, [t, pendingEvaluations, backlogFamilies, overdueMedical, staleQueueCount, prediction, predictionFailed]);

  if (loading) {
    return (
      <div className="animate-pulse rounded-lg border border-border/50 bg-card p-3">
        <div className="mb-2 h-3 w-32 rounded bg-muted" />
        <div className="h-7 rounded-md bg-muted" />
        <div className="mt-2 h-7 rounded-md bg-muted" />
      </div>
    );
  }

  return (
    <div className="flex h-full flex-col rounded-lg border border-border/50 bg-card shadow-sm">
      <div className="flex items-center gap-2 border-b border-border/35 bg-muted/15 px-3 py-2.5">
        <Bell className="size-3 text-muted-foreground" />
        <span className="text-[11px] font-bold text-foreground">{t("tables.latest_alerts_title")}</span>
      </div>
      <ul className="max-h-[280px] flex-1 divide-y divide-border/30 overflow-y-auto">
        {rows.length === 0 ? (
          <li className="px-3 py-6 text-center text-[11px] text-muted-foreground">{t("common.empty_feed")}</li>
        ) : (
          rows.map((it) => (
            <li key={it.id} className="flex gap-2 px-3 py-2">
              <span
                className={cn(
                  "mt-1 size-1.5 shrink-0 rounded-full",
                  it.tone === "rose" ? "bg-destructive" : it.tone === "amber" ? "bg-warning" : "bg-primary"
                )}
              />
              <div className="min-w-0 flex-1">
                <p className="text-[11px] leading-snug text-foreground">{it.text}</p>
                <div className="mt-0.5 flex flex-wrap items-center gap-x-2 gap-y-0 text-[10px] text-muted-foreground">
                  {it.count != null ? (
                    <span className="tabular-nums" dir="ltr">
                      {it.count.toLocaleString()}
                    </span>
                  ) : null}
                  <span className="tabular-nums" suppressHydrationWarning>
                    {hydrated ? t("feed.minutes_ago", { count: it.minutesAgo }) : "\u00a0"}
                  </span>
                </div>
              </div>
            </li>
          ))
        )}
      </ul>
      <div className="mt-auto border-t border-border/35 px-3 py-2">
        <Link
          href="/dashboard/families"
          className="inline-flex items-center gap-1 text-[11px] font-medium text-primary hover:underline"
        >
          {t("common.view_all")}
          <Chevron className="size-3 opacity-70" />
        </Link>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { Skeleton } from "@/components/ui/skeleton";
import {
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
  Tooltip,
  Legend,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  LineChart,
  Line,
} from "recharts";
import { useTranslations } from "next-intl";
import { cn } from "@/lib/utils";

const PLOT_H = 200;

type ClassSlice = {
  classificationKey?: string;
  value: number;
  fill?: string;
};

type MonthlyRow = {
  monthLabelShort?: string;
  householdIncome?: number;
  householdExpenses?: number;
  medicalSpend?: number;
};

export interface AnalyticsGridProps {
  familyClassification: ClassSlice[];
  classificationExpenses: ClassSlice[];
  monthlySeries?: MonthlyRow[];
  loading?: boolean;
}

function Panel({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <div className="flex min-h-0 flex-col overflow-hidden rounded-lg border border-border/50 bg-card shadow-sm">
      <div className="border-b border-border/40 bg-muted/15 px-3 py-2">
        <h3 className="text-[11px] font-semibold leading-tight text-muted-foreground">{title}</h3>
      </div>
      <div className="min-h-[200px] flex-1 p-2">{children}</div>
    </div>
  );
}

function DashTooltip({ active, payload }: { active?: boolean; payload?: { value: number; name: string }[] }) {
  if (active && payload?.length) {
    return (
      <div className="rounded-md border border-border bg-popover/95 px-2 py-1.5 text-xs shadow-md">
        <p className="font-medium text-foreground">{payload[0].name}</p>
        <p className="font-semibold tabular-nums text-primary" dir="ltr">
          {Number(payload[0].value ?? 0).toLocaleString()}
        </p>
      </div>
    );
  }
  return null;
}

const donutLegend = {
  layout: "vertical" as const,
  align: "right" as const,
  verticalAlign: "middle" as const,
  iconType: "circle" as const,
  wrapperStyle: { fontSize: 10, paddingLeft: 4 },
  formatter: (value: string) => <span className="text-[10px] text-foreground/90">{value}</span>,
};

function AnalyticsGridInner({
  familyClassification,
  classificationExpenses,
  monthlySeries,
  loading,
}: AnalyticsGridProps) {
  const t = useTranslations("dashboard");
  const gradId = React.useId().replace(/:/g, "");

  const pieClass = React.useMemo(
    () =>
      (familyClassification || []).map((c) => ({
        ...c,
        name: c.classificationKey ? t(`classification.${c.classificationKey}` as const) : "?",
      })),
    [familyClassification, t]
  );

  const pieExpense = React.useMemo(
    () =>
      (classificationExpenses || []).map((c) => ({
        ...c,
        name: c.classificationKey ? t(`classification.${c.classificationKey}` as const) : "?",
      })),
    [classificationExpenses, t]
  );

  const trendPayload = monthlySeries ?? [];
  const medicalBars = React.useMemo(() => trendPayload.slice(-6), [trendPayload]);

  const trendHas = trendPayload.length > 0;
  const pieClassEmpty = pieClass.length === 0 || pieClass.every((s) => !s.value);
  const pieExpEmpty = pieExpense.length === 0 || pieExpense.every((s) => !s.value);
  const medHas = medicalBars.some((m) => (m.medicalSpend ?? 0) > 0);

  if (loading) {
    return (
      <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">
        {Array.from({ length: 4 }).map((_, i) => (
          <div key={i} className="overflow-hidden rounded-lg border border-border/50 bg-card">
            <Skeleton className="h-9 w-full rounded-none" />
            <Skeleton className="m-2 h-[200px] rounded-md" />
          </div>
        ))}
      </div>
    );
  }

  const margin = { top: 8, right: 8, left: 0, bottom: 4 };

  return (
    <section className="space-y-2">
      <h2 className="text-sm font-bold text-foreground">{t("sections.core_analytics")}</h2>
      <div
        className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4"
        dir="ltr"
        style={{ direction: "ltr" }}
      >
        {/* 1 — classification donut */}
        <Panel title={t("charts.classification_distribution")}>
          <div className="h-[200px] w-full">
            {pieClassEmpty ? (
              <div className="flex h-full items-center justify-center px-3 text-center text-[11px] text-muted-foreground">
                {t("charts.empty_classification")}
              </div>
            ) : (
              <ResponsiveContainer width="100%" height="100%">
                <PieChart margin={{ top: 4, bottom: 4, left: 4, right: 4 }}>
                  <Pie
                    data={pieClass}
                    dataKey="value"
                    cx="38%"
                    cy="50%"
                    innerRadius={38}
                    outerRadius={62}
                    paddingAngle={2}
                    animationDuration={500}
                  >
                    {pieClass.map((entry, idx) => (
                      <Cell key={`${entry.classificationKey ?? idx}`} fill={entry.fill || "var(--chart-1)"} />
                    ))}
                  </Pie>
                  <Tooltip content={<DashTooltip />} />
                  <Legend {...donutLegend} />
                </PieChart>
              </ResponsiveContainer>
            )}
          </div>
        </Panel>

        {/* 2 — expense distribution donut */}
        <Panel title={t("charts.expense_distribution_donut")}>
          <div className="h-[200px] w-full">
