                  <SelectTrigger className="w-full sm:w-48"><SelectValue placeholder={tM("selectPh")} /></SelectTrigger>
                    <SelectContent>
                      {MARITAL_OPTIONS.map((s) => (
                        <SelectItem key={s.value} value={s.value}>
                          {dictLabel(t, "marital", s)}
